<?php
namespace Tests\Feature;use App\Models\Company;use App\Models\Contact;use App\Models\Opportunity;use App\Models\Pipeline;use App\Models\PipelineStage;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Laravel\Sanctum\Sanctum;use Tests\TestCase;class OpportunityTest extends TestCase{    use RefreshDatabase;    protected function setUp(): void    {        parent::setUp();        $this->user = User::factory()->create();        Sanctum::actingAs($this->user, ['*']);        $this->pipeline = Pipeline::create([            'name' => 'Pipeline Teste',            'slug' => 'pipeline-teste',        ]);        $this->pipelineStage = PipelineStage::create([            'pipeline_id' => $this->pipeline->id,            'name' => 'Prospecção',            'slug' => 'prospeccao',        ]);        $this->company = $this->createCompany([            'corporate_name' => 'Empresa Teste Ltda',            'trade_name' => 'Empresa Teste',            'tax_id' => '12345678000190',            'status' => 'prospecting',        ]);        $this->contact = Contact::create([            'name' => 'Contato Teste',            'email' => 'contato@teste.com',            'company_id' => $this->company->id,        ]);        $this->opportunityData = [            'code' => 'OP-001',            'title' => 'Oportunidade de Teste',            'owner_id' => $this->user->id,            'company_id' => $this->company->id,            'primary_contact_id' => $this->contact->id,            'pipeline_id' => $this->pipeline->id,            'stage_id' => $this->pipelineStage->id,            'status' => 'open',        ];    }    /**     * Teste: listar oportunidades com sucesso (index).     */    public function test_list_opportunities_success(): void    {        foreach (range(1, 3) as $i) {            $this->createOpportunity([                'code' => "OP-00{$i}",                'title' => "Oportunidade {$i}",                'company_id' => $this->company->id,                'pipeline_id' => $this->pipeline->id,                'stage_id' => $this->pipelineStage->id,                'status' => 'open',            ]);        }        $response = $this->get('/api/v1/opportunities');        $response->assertStatus(200);        $response->assertJson([            'success' => true,            'status' => 200,        ]);        $response->assertJsonStructure([            'data' => [                'items',                'pagination',            ],            'message',            'status',        ]);    }    /**     * Teste: buscar oportunidade por ID com sucesso (show).     */    public function test_show_opportunity_success(): void    {        $opportunity = $this->createOpportunity([            'code' => 'OP-BUSCA',            'title' => 'Oportunidade para Buscar',            'company_id' => $this->company->id,            'pipeline_id' => $this->pipeline->id,            'stage_id' => $this->pipelineStage->id,            'status' => 'open',        ]);        $response = $this->get("/api/v1/opportunities/{$opportunity->id}");        $response->assertStatus(200);        $response->assertJson([            'success' => true,            'status' => 200,            'message' => 'Oportunidade encontrada.',        ]);        $response->assertJsonStructure([            'data' => [                'id',                'code',                'title',                'company_id',                'pipeline_id',                'stage_id',                'status',            ],            'message',            'status',        ]);    }    /**     * Teste: buscar oportunidade inexistente retorna 404.     */    public function test_show_opportunity_not_found(): void    {        $response = $this->get('/api/v1/opportunities/99999');        $response->assertStatus(404);        $response->assertJson([            'success' => false,            'status' => 404,        ]);    }    /**     * Teste: criar oportunidade com sucesso (store).     */    public function test_store_opportunity_success(): void    {        $response = $this->post('/api/v1/opportunities', $this->opportunityData);        $response->assertStatus(201);        $response->assertJson([            'success' => true,            'status' => 201,            'message' => 'Oportunidade criada com sucesso.',        ]);        $response->assertJsonStructure([            'data' => [                'id',                'code',                'title',                'company_id',                'pipeline_id',                'stage_id',                'status',            ],            'message',            'status',        ]);        $this->assertDatabaseHas('opportunities', [            'code' => 'OP-001',            'title' => 'Oportunidade de Teste',        ]);    }    /**     * Teste: criar oportunidade com dados inválidos retorna erro de validação.     */    public function test_store_opportunity_validation_error(): void    {        $invalidData = [            'code' => '',            'title' => '',            'company_id' => '',            'pipeline_id' => '',            'stage_id' => '',            'status' => '',        ];        $response = $this->post('/api/v1/opportunities', $invalidData);        $response->assertStatus(422);        $response->assertJsonValidationErrors([            'code',            'title',            'company_id',            'pipeline_id',            'stage_id',            'status',        ]);    }    /**     * Teste: atualizar oportunidade com sucesso (update).     */    public function test_update_opportunity_success(): void    {        $opportunity = $this->createOpportunity([            'code' => 'OP-ORIGINAL',            'title' => 'Oportunidade Original',            'company_id' => $this->company->id,            'pipeline_id' => $this->pipeline->id,            'stage_id' => $this->pipelineStage->id,            'status' => 'open',        ]);        $updateData = [            'title' => 'Oportunidade Atualizada',            'status' => 'won',        ];        $response = $this->put("/api/v1/opportunities/{$opportunity->id}", $updateData);        $response->assertStatus(200);        $response->assertJson([            'success' => true,            'message' => 'Oportunidade atualizada com sucesso.',        ]);        $this->assertDatabaseHas('opportunities', [            'id' => $opportunity->id,            'title' => 'Oportunidade Atualizada',        ]);    }    /**     * Teste: atualizar oportunidade inexistente retorna 404.     */    public function test_update_opportunity_not_found(): void    {        $response = $this->put('/api/v1/opportunities/99999', [            'title' => 'Novo Título',        ]);        $response->assertStatus(404);        $response->assertJson([            'success' => false,            'status' => 404,        ]);    }    /**     * Teste: excluir oportunidade com sucesso (destroy).     */    public function test_destroy_opportunity_success(): void    {        $opportunity = $this->createOpportunity([            'code' => 'OP-EXCLUIR',            'title' => 'Oportunidade para Excluir',            'company_id' => $this->company->id,            'pipeline_id' => $this->pipeline->id,            'stage_id' => $this->pipelineStage->id,            'status' => 'open',        ]);        $response = $this->delete("/api/v1/opportunities/{$opportunity->id}");        $response->assertStatus(200);        $response->assertJson([            'success' => true,            'message' => 'Oportunidade removida com sucesso.',        ]);        $this->assertSoftDeleted('opportunities', [            'id' => $opportunity->id,        ]);    }    /**     * Teste: excluir oportunidade inexistente retorna 404.     */    public function test_destroy_opportunity_not_found(): void    {        $response = $this->delete('/api/v1/opportunities/99999');        $response->assertStatus(404);        $response->assertJson([            'success' => false,            'status' => 404,        ]);    }    /**     * Teste: rota sem autenticação retorna 401.     */    public function test_unauthenticated_request_returns_401(): void    {                $this->app['auth']->forgetGuards();

        $response = $this->get('/api/v1/opportunities');        $response->assertStatus(401);    }}